"""Seating charts: students sorted by last name in rows."""

from typing import List

from rosterkit.models import Student
from rosterkit.errors import ProjectError


def _sorted_names(students: List[Student]) -> List[str]:
    key = lambda stud: (stud.last_name, stud.first_name)
    ordered = sorted(students, key=key)
    return [stud.display_name for stud in ordered]


def _split(names: List[str], size: int) -> List[List[str]]:
    span = range(0, len(names), size)
    return [names[pos:pos + size] for pos in span]


def _line(number: int, row: List[str]) -> str:
    return f"Row {number}: " + " | ".join(row)


# ---
def seating_rows(students, per_row):
    if per_row <= 0 or not students:
        raise ProjectError("need students and seats")
    names = _sorted_names(students)
    rows = _split(names, per_row)
    return [_line(*pair) for pair in enumerate(rows, 1)]

