import unittest

from rosterkit.seating import seating_rows
from rosterkit.models import Student
from rosterkit.errors import ProjectError


def _pupil(last, first):
    return Student("1", last, first, "A")


class SeatingTests(unittest.TestCase):
    def test_sorted_and_chunked(self):
        pupils = [
            _pupil("Halloway", "Juno"),
            _pupil("Dunmere", "Piet"),
            _pupil("Adler", "Rhea")
        ]
        self.assertEqual(
            seating_rows(pupils, 2),
            [
                "Row 1: Adler, Rhea | Dunmere, Piet",
                "Row 2: Halloway, Juno"
            ]
        )

    def test_bad_seat_count(self):
        pupils = [_pupil("Adler", "Rhea")]
        for count in (0, -1):
            with self.assertRaises(ProjectError):
                seating_rows(pupils, count)

    def test_no_students(self):
        with self.assertRaises(ProjectError):
            seating_rows([], 3)
